//! Original synthetic saved-wire contracts, without runtime feature gates.
//!
//! Existing literal session/deployment fixtures supply data only. Expected
//! modes, policies, epochs, cardinalities and refusals below are independent
//! literals, not results generated by a producer or comparison implementation.

use super::*;

fn with_session(session: Value, form_login: bool, epoch: u8, committed: bool) -> Value {
    let mut document = deployment_aware_wordpress_document('2');
    document["supplied_session"] = session;
    let discovery = &mut document["wordpress_discovery"];
    discovery["schema"] = json!("security.wordpress-discovery-audit/v4");
    discovery["policy_id"] = json!(if form_login {
        "termivar.wordpress-supplied-session-metadata-discovery/v2"
    } else {
        "termivar.wordpress-supplied-session-metadata-discovery/v1"
    });
    // This REST source was already observed at the anonymous entry. It does
    // not acquire supporting provenance merely because a session is selected.
    discovery["sources"][0]["source_supplied_session_page_references"] = json!([]);
    discovery["supplied_session_pages"] = json!({
        "mode": if form_login {
            "form_login_supplied_session_resources"
        } else {
            "committed_supplied_session_resources"
        },
        "policy_reference":format!("supplied-session-policy-sha256:{}", "1".repeat(64)),
        "application_reference":format!("supplied-session-application-sha256:{}", "2".repeat(64)),
        "principal_reference":"supplied-session-principal-0001",
        "credential_mechanism":if form_login { "cookie_jar" } else { "authorization_header" },
        "session_epoch":epoch,
        "selected_count":1,
        "committed_count":u8::from(committed),
        "accepted_association_count":u8::from(committed),
        "rejected_association_count":0,
        "not_established_association_count":u8::from(!committed),
        "not_evaluated_count":u8::from(!committed),
        "interpreted_response_bytes":if committed { 23 } else { 0 },
        "pages":[{
            "page_reference":format!("sha256:{}", "f".repeat(64)),
            "resource_reference":format!("supplied-session-resource-sha256:{}", "5".repeat(64)),
            "resource_evidence_reference":if committed {
                json!(format!("supplied-session-resource-evidence-sha256:{}", "6".repeat(64)))
            } else { Value::Null },
            "acquisition":"reused_supplied_session_response",
            "association":if committed { "accepted" } else { "not_established" },
            "outcome":if committed { "accepted" } else { "not_evaluated" },
            "interpreted_response_bytes":if committed { 23 } else { 0 },
            "evidence_reference_count":u8::from(committed),
            "evidence_references":if committed { json!(["evidence-0002"]) } else { json!([]) },
            "fingerprint_evaluation":"not_selected_in_v1"
        }]
    });
    if committed {
        document["items"][1]["evidence_count"] = json!(2);
        document["items"][1]["evidence_references"] = json!(["evidence-0001", "evidence-0002"]);
    }
    document
}

fn positive() -> Value {
    with_session(supplied_session_form_login_audit(), true, 1, true)
}

fn selected_empty() -> Value {
    with_session(supplied_session_form_login_failure_audit(), true, 0, false)
}

fn acquired_cookie_but_unhealthy_startup() -> Value {
    let mut session = supplied_session_form_login_audit();
    session["outcome"] = json!("startup_unhealthy");
    session["coverage"] = json!("none");
    session["checkpoints"] = json!([{
        "sequence":0,"phase":"startup","after_subject_count":0,
        "evidence_reference":format!("supplied-session-checkpoint-evidence-sha256:{}", "7".repeat(64)),
        "outcome":"unhealthy","status":200,"body_state":"complete",
        "predicate":"not_matched","response_bytes":17
    }]);
    let resource = &mut session["resources"][0];
    resource["evidence_reference"] = Value::Null;
    resource["outcome"] = json!("not_dispatched");
    resource["status"] = Value::Null;
    resource["response_bytes"] = json!(0);
    // Planned resources retain epoch one; authenticated context has not been
    // established, even though the login POST returned a selected cookie.
    resource["epoch"] = json!(1);
    session["dispatched_resource_count"] = json!(0);
    session["committed_resource_count"] = json!(0);
    session["dispatched_request_count"] = json!(3);
    session["response_bytes"] = json!(71);
    session["cookie_lifecycle"]["final_epoch"] = json!(0);
    session["login"]["final_epoch"] = json!(0);
    with_session(session, true, 0, false)
}

fn ready_cookie_audit() -> Value {
    let mut session = supplied_session_form_login_audit();
    session["schema"] = json!("security.supplied-session-audit/v2");
    session
        .as_object_mut()
        .unwrap()
        .remove("credential_acquisition");
    session.as_object_mut().unwrap().remove("login");
    session["cookie_lifecycle"]["initial_epoch"] = json!(1);
    session["dispatched_request_count"] = json!(3);
    session["response_bytes"] = json!(59);
    session
}

fn reject_named(document: &Value, label: &str) {
    assert!(
        compare_reports(&bytes(document), SAMPLE, ComparisonFormat::Json).is_err(),
        "accepted invalid synthetic WordPress form-login wire: {label}"
    );
}

#[test]
fn wordpress_form_login_saved_reader_accepts_epoch_one_and_selected_empty_epoch_zero() {
    for (label, document, epoch, committed) in [
        ("healthy", positive(), 1, 1),
        ("missing csrf", selected_empty(), 0, 0),
        (
            "cookie acquired but startup unhealthy",
            acquired_cookie_but_unhealthy_startup(),
            0,
            0,
        ),
    ] {
        let comparison = compare(&document, &document);
        assert_eq!(
            comparison["schema"], "termivar-report-comparison/v1",
            "{label}"
        );
        assert_eq!(group(&comparison, "unchanged").len(), 2, "{label}");
        for field in ["only_in_before", "only_in_after", "changed"] {
            assert!(group(&comparison, field).is_empty(), "{label}: {field}");
        }
        let wordpress = wordpress_comparison(&comparison);
        assert_eq!(wordpress["status"], "compared", "{label}");
        assert_eq!(wordpress["methodology"]["status"], "unchanged", "{label}");
        // These historical review literals have no declared inventory-coverage
        // record. Equal source projections do not establish security coverage.
        assert_eq!(
            wordpress["coverage"]["status"], "not_established",
            "{label}"
        );
        let saved = &comparison["after"]["optional_audits"]["wordpress_discovery"];
        assert_eq!(
            saved["supplied_session_pages"]["session_epoch"], epoch,
            "{label}"
        );
        assert_eq!(
            saved["supplied_session_pages"]["selected_count"], 1,
            "{label}"
        );
        assert_eq!(
            saved["supplied_session_pages"]["committed_count"], committed,
            "{label}"
        );
        assert_eq!(
            document["supplied_session"]["resources"][0]["epoch"], 1,
            "{label}"
        );
    }
    let comparison = compare(&selected_empty(), &positive());
    assert_eq!(wordpress_comparison(&comparison)["status"], "not_compared");
    assert_eq!(
        wordpress_comparison(&comparison)["reason"],
        "supplied_session_context_mismatch"
    );
}

#[test]
fn wordpress_form_login_saved_reader_preserves_ready_v1_and_v2_contracts() {
    for (label, session) in [
        ("v1 header", supplied_session_audit()),
        ("v2 cookie", ready_cookie_audit()),
    ] {
        let mechanism = session["credential_mechanism"].clone();
        let mut document = with_session(session, false, 1, true);
        document["wordpress_discovery"]["supplied_session_pages"]["credential_mechanism"] =
            mechanism;
        let comparison = compare(&document, &document);
        assert_eq!(
            wordpress_comparison(&comparison)["status"],
            "compared",
            "{label}"
        );
        assert_eq!(group(&comparison, "unchanged").len(), 2, "{label}");
        assert_eq!(
            document["wordpress_discovery"]["policy_id"],
            "termivar.wordpress-supplied-session-metadata-discovery/v1"
        );
    }
}

#[test]
fn wordpress_form_login_saved_reader_rejects_missing_bool_duplicate_and_malformed_rows() {
    let valid = positive();
    compare(&valid, &valid);
    for field in [
        "mode",
        "policy_reference",
        "session_epoch",
        "selected_count",
        "committed_count",
        "pages",
    ] {
        let mut invalid = valid.clone();
        invalid["wordpress_discovery"]["supplied_session_pages"]
            .as_object_mut()
            .unwrap()
            .remove(field);
        reject_named(&invalid, field);
    }
    for (path, value) in [
        (
            "/wordpress_discovery/supplied_session_pages/session_epoch",
            json!(true),
        ),
        (
            "/wordpress_discovery/supplied_session_pages/selected_count",
            json!(true),
        ),
        (
            "/wordpress_discovery/supplied_session_pages/committed_count",
            json!(false),
        ),
        (
            "/wordpress_discovery/supplied_session_pages/interpreted_response_bytes",
            json!(true),
        ),
        (
            "/wordpress_discovery/supplied_session_pages/pages",
            Value::Null,
        ),
        (
            "/wordpress_discovery/supplied_session_pages/pages/0",
            json!("not a row"),
        ),
        (
            "/wordpress_discovery/supplied_session_pages/pages/0/evidence_reference_count",
            json!(true),
        ),
        (
            "/wordpress_discovery/sources/0/source_supplied_session_page_references",
            Value::Null,
        ),
    ] {
        let mut invalid = valid.clone();
        *invalid.pointer_mut(path).unwrap() = value;
        reject_named(&invalid, path);
    }
    let mut duplicated = valid.clone();
    let row = duplicated["wordpress_discovery"]["supplied_session_pages"]["pages"][0].clone();
    duplicated["wordpress_discovery"]["supplied_session_pages"]["pages"] =
        json!([row.clone(), row]);
    for field in [
        "selected_count",
        "committed_count",
        "accepted_association_count",
    ] {
        duplicated["wordpress_discovery"]["supplied_session_pages"][field] = json!(2);
    }
    duplicated["wordpress_discovery"]["supplied_session_pages"]["interpreted_response_bytes"] =
        json!(46);
    reject_named(
        &duplicated,
        "duplicate page/resource identities despite reconciled page totals",
    );

    let raw = serde_json::to_string(&valid).unwrap();
    let duplicated_key = raw.replacen(
        "\"session_epoch\":1",
        "\"session_epoch\":1,\"session_epoch\":1",
        1,
    );
    assert_ne!(
        raw, duplicated_key,
        "literal duplicate-key mutation must execute"
    );
    assert!(compare_reports(duplicated_key.as_bytes(), SAMPLE, ComparisonFormat::Json).is_err());
}

#[test]
fn wordpress_form_login_saved_reader_rejects_cross_context_and_source_substitution() {
    let valid = positive();
    compare(&valid, &valid);
    for (path, value) in [
        (
            "/wordpress_discovery/supplied_session_pages/policy_reference",
            json!(format!("supplied-session-policy-sha256:{}", "9".repeat(64))),
        ),
        (
            "/wordpress_discovery/supplied_session_pages/application_reference",
            json!(format!(
                "supplied-session-application-sha256:{}",
                "9".repeat(64)
            )),
        ),
        (
            "/wordpress_discovery/supplied_session_pages/principal_reference",
            json!("supplied-session-principal-0002"),
        ),
        (
            "/wordpress_discovery/supplied_session_pages/credential_mechanism",
            json!("authorization_header"),
        ),
        (
            "/wordpress_discovery/supplied_session_pages/pages/0/resource_reference",
            json!(format!(
                "supplied-session-resource-sha256:{}",
                "9".repeat(64)
            )),
        ),
        (
            "/wordpress_discovery/supplied_session_pages/pages/0/resource_evidence_reference",
            json!(format!(
                "supplied-session-resource-evidence-sha256:{}",
                "9".repeat(64)
            )),
        ),
        (
            "/wordpress_discovery/sources/0/source_supplied_session_page_references",
            json!([format!("sha256:{}", "9".repeat(64))]),
        ),
        (
            "/wordpress_discovery/sources/0/source_supplied_session_page_references",
            json!([
                format!("sha256:{}", "f".repeat(64)),
                format!("sha256:{}", "f".repeat(64))
            ]),
        ),
        (
            "/wordpress_discovery/sources/0/evidence_references",
            json!(["evidence-0002"]),
        ),
    ] {
        let mut invalid = valid.clone();
        *invalid.pointer_mut(path).unwrap() = value;
        reject_named(&invalid, path);
    }
    let mut absent = valid.clone();
    absent["wordpress_discovery"]["sources"][0]
        .as_object_mut()
        .unwrap()
        .remove("source_supplied_session_page_references");
    reject_named(
        &absent,
        "missing explicit entry-source session provenance array",
    );
}

#[test]
fn wordpress_form_login_saved_reader_rejects_policy_mode_and_acquisition_swaps() {
    let valid = positive();
    compare(&valid, &valid);
    for (label, mode, policy, session) in [
        (
            "new mode old policy",
            "form_login_supplied_session_resources",
            "termivar.wordpress-supplied-session-metadata-discovery/v1",
            supplied_session_form_login_audit(),
        ),
        (
            "old mode new policy",
            "committed_supplied_session_resources",
            "termivar.wordpress-supplied-session-metadata-discovery/v2",
            supplied_session_form_login_audit(),
        ),
        (
            "v3 under legacy",
            "committed_supplied_session_resources",
            "termivar.wordpress-supplied-session-metadata-discovery/v1",
            supplied_session_form_login_audit(),
        ),
        (
            "v2 under form",
            "form_login_supplied_session_resources",
            "termivar.wordpress-supplied-session-metadata-discovery/v2",
            ready_cookie_audit(),
        ),
        (
            "v5 under form",
            "form_login_supplied_session_resources",
            "termivar.wordpress-supplied-session-metadata-discovery/v2",
            supplied_session_oauth_code_audit(),
        ),
    ] {
        // Each source audit must independently pass the public reader before
        // it is combined with an intentionally incompatible WordPress mode.
        let mut standalone = report(Vec::new());
        standalone["supplied_session"] = session.clone();
        compare(&standalone, &standalone);
        let mut invalid = valid.clone();
        invalid["supplied_session"] = session;
        invalid["wordpress_discovery"]["policy_id"] = json!(policy);
        invalid["wordpress_discovery"]["supplied_session_pages"]["mode"] = json!(mode);
        reject_named(&invalid, label);
    }
    for schema in [
        "security.supplied-session-audit/v4",
        "security.supplied-session-audit/v6",
        "security.supplied-session-audit/v7",
    ] {
        let mut invalid = valid.clone();
        invalid["supplied_session"]["schema"] = json!(schema);
        reject_named(
            &invalid,
            "unsupported acquisition cannot be enabled by a schema-only relabel",
        );
    }
}

#[test]
fn wordpress_form_login_saved_reader_keeps_epoch_zero_empty_and_planned_resources_at_one() {
    for document in [selected_empty(), acquired_cookie_but_unhealthy_startup()] {
        compare(&document, &document);
        for (path, value) in [
            (
                "/wordpress_discovery/supplied_session_pages/session_epoch",
                json!(1),
            ),
            ("/supplied_session/resources/0/epoch", json!(0)),
            (
                "/wordpress_discovery/supplied_session_pages/committed_count",
                json!(1),
            ),
            (
                "/wordpress_discovery/supplied_session_pages/pages/0/resource_evidence_reference",
                json!(format!(
                    "supplied-session-resource-evidence-sha256:{}",
                    "6".repeat(64)
                )),
            ),
            (
                "/wordpress_discovery/supplied_session_pages/pages/0/evidence_references",
                json!(["evidence-0002"]),
            ),
            (
                "/wordpress_discovery/sources/0/source_supplied_session_page_references",
                json!([format!("sha256:{}", "f".repeat(64))]),
            ),
        ] {
            let mut invalid = document.clone();
            *invalid.pointer_mut(path).unwrap() = value;
            reject_named(&invalid, path);
        }
    }
    let mut final_epoch_mismatch = positive();
    final_epoch_mismatch["supplied_session"]["cookie_lifecycle"]["final_epoch"] = json!(0);
    final_epoch_mismatch["supplied_session"]["login"]["final_epoch"] = json!(0);
    reject_named(
        &final_epoch_mismatch,
        "healthy committed page cannot survive final epoch zero",
    );
}
